154	    @Override
155	    @Transactional(readOnly = true)
156	    public Collection<PetType> findAllPetTypes() throws DataAccessException {
157	        return petTypeRepository.findAll();
158	    }
159	
160	    @Override
161	    @Transactional
162	    public void savePetType(PetType petType) throws DataAccessException {
163	        petTypeRepository.save(petType);
164	    }
