234	    @Override
235	    @Transactional
236	    public void saveOwner(Owner owner) throws DataAccessException {
237	        if (owner.isNew() && owner.getCustomerCode() == null) {
238	            owner.setCustomerCode(generateCustomerCode(owner.getLastName()));
239	        }
240	        ownerRepository.save(owner);
241	
242	    }
243	
244	    /**
245	     * Build a customer code formatted {@code '<LAST3>-<NNNN>'}, where {@code LAST3} is the
246	     * upper-cased first three letters of the owner's last name and {@code NNNN} is a global,
247	     * 4-digit zero-padded sequence equal to one more than the current number of owners
248	     * (e.g. {@code 'SMI-0007'}).
249	     */
250	    private String generateCustomerCode(String lastName) {
251	        String name = lastName == null ? "" : lastName;
252	        String last3 = name.substring(0, Math.min(3, name.length())).toUpperCase();
253	        long sequence = ownerRepository.findAll().size() + 1L;
254	        return String.format("%s-%04d", last3, sequence);
255	    }
256	
257	    @Override
258	    @Transactional(readOnly = true)
259	    public boolean isTelephoneInUse(String telephone) throws DataAccessException {
260	        String normalized = normalizeTelephone(telephone);
261	        if (normalized == null) {
262	            return false;
263	        }
264	        return ownerRepository.findAll().stream()
265	            .map(owner -> normalizeTelephone(owner.getTelephone()))
266	            .anyMatch(normalized::equals);
267	    }
268	
269	    /**
270	     * Reduces a telephone number to its canonical E.164 form so that differently formatted but
271	     * equivalent numbers compare equal. A value already stored that cannot form valid E.164
272	     * (e.g. unusual legacy data) falls back to its digits-only form rather than failing lookup.
273	     */
274	    private static String normalizeTelephone(String telephone) {
275	        if (telephone == null) {
276	            return null;
277	        }
278	        try {
279	            return TelephoneNormalizer.toE164(telephone);
280	        } catch (InvalidTelephoneException ex) {
281	            return telephone.replaceAll("\\D", "");
282	        }
283	    }
284	
285	    @Override
286	    @Transactional(readOnly = true)
287	    public Collection<Owner> findOwnerByLastName(String lastName) throws DataAccessException {
288	        return ownerRepository.findByLastName(lastName);
289	    }
